package com.familyguard.child;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.os.Build;import android.widget.*;
import com.google.firebase.FirebaseApp;import com.google.firebase.auth.FirebaseAuth;import com.google.firebase.firestore.*;import java.util.*;
public class MainActivity extends Activity{
 LinearLayout root;EditText code;TextView status;FirebaseAuth auth;FirebaseFirestore db;String parentUid;ListenerRegistration listener;Button startLocation;
 public void onCreate(Bundle b){super.onCreate(b);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(32,40,32,24);root.setBackgroundColor(0xFFF5F7FB);TextView title=new TextView(this);title.setText("FamilyGuard Child");title.setTextSize(27);TextView info=new TextView(this);info.setText("Pairing and location sharing are visible on this device.");code=new EditText(this);code.setSingleLine(true);code.setHint("8-character Parent code");Button pair=new Button(this);pair.setText("Pair with Parent");pair.setOnClickListener(v->pair());status=new TextView(this);status.setText("Connecting to Firebase...");root.addView(title);root.addView(info);root.addView(code);root.addView(pair);root.addView(status);setContentView(root);try{FirebaseApp.initializeApp(this);auth=FirebaseAuth.getInstance();db=FirebaseFirestore.getInstance();auth.signInAnonymously().addOnSuccessListener(x->status.setText("Connected. Enter the code from Parent app.")).addOnFailureListener(e->status.setText("Sign-in failed: "+e.getMessage()));}catch(Exception e){status.setText("Firebase setup error: "+e.getMessage());}}
 void pair(){String c=code.getText().toString().trim().toUpperCase(Locale.US);if(c.length()!=8){status.setText("Enter the full 8-character code.");return;}db.collection("pairCodes").document(c).get().addOnSuccessListener(doc->{if(!doc.exists()){status.setText("Invalid code.");return;}Date exp=doc.getDate("expiresAt");String p=doc.getString("parentUid");String used=doc.getString("consumedBy");if(exp==null||exp.before(new Date())||p==null||(used!=null&&!used.isEmpty())){status.setText("Code expired or already used.");return;}parentUid=p;String uid=auth.getUid();db.collection("pairCodes").document(c).update("consumedBy",uid).addOnSuccessListener(v->{Map<String,Object>link=new HashMap<>();link.put("parentUid",p);link.put("childUid",uid);link.put("childLabel",Build.MODEL);link.put("pairCode",c);link.put("pairedAt",FieldValue.serverTimestamp());db.collection("familyLinks").document(uid).set(link).addOnSuccessListener(x->{getSharedPreferences("familyguard_child",MODE_PRIVATE).edit().putString("parent_uid",p).apply();status.setText("Paired. Request Location permission from Parent.");showRequests();}).addOnFailureListener(e->status.setText("Link failed: "+e.getMessage()));}).addOnFailureListener(e->status.setText("Code was already used or could not be confirmed."));}).addOnFailureListener(e->status.setText("Pairing lookup failed: "+e.getMessage()));}
 void showRequests(){String[] names={"Location","Camera","Microphone","Usage Access","Notifications"};for(String n:names){Button b=new Button(this);b.setText("Request "+n);b.setOnClickListener(v->request(n));root.addView(b);}startLocation=new Button(this);startLocation.setText("Start visible location sharing");startLocation.setEnabled(false);startLocation.setOnClickListener(v->startLocationSharing());root.addView(startLocation);watch();}
 void request(String permission){Map<String,Object>d=new HashMap<>();d.put("parentUid",parentUid);d.put("childUid",auth.getUid());d.put("childLabel",Build.MODEL);d.put("permission",permission);d.put("status","pending");d.put("createdAt",FieldValue.serverTimestamp());db.collection("approvalRequests").add(d).addOnSuccessListener(x->status.setText(permission+" request sent. Wait for Parent approval.")).addOnFailureListener(e->status.setText("Request failed: "+e.getMessage()));}
 void watch(){if(listener!=null)listener.remove();listener=db.collection("approvalRequests").whereEqualTo("childUid",auth.getUid()).addSnapshotListener((s,e)->{if(e!=null||s==null)return;for(DocumentSnapshot d:s){String state=d.getString("status");String permission=d.getString("permission");if("approved".equals(state)){status.setText("Parent approved "+permission+". Confirm Android permission on this phone.");if("Location".equals(permission))requestLocationPermission();else if("Camera".equals(permission))requestSystemPermission(android.Manifest.permission.CAMERA,101);else if("Microphone".equals(permission))requestSystemPermission(android.Manifest.permission.RECORD_AUDIO,102);}else if("denied".equals(state))status.setText("Parent denied "+permission+".");}});}
 void requestLocationPermission(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},103);}else enableLocationStart();}
 void requestSystemPermission(String p,int c){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(p)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{p},c);else status.setText(p+" permission already granted. Capture still requires a separate visible session.");}
 void enableLocationStart(){if(startLocation!=null)startLocation.setEnabled(true);status.setText("Location permission granted. Tap Start visible location sharing when ready.");}
 void startLocationSharing(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED&&checkSelfPermission(android.Manifest.permission.ACCESS_COARSE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED){status.setText("Location permission is required first.");return;}Intent i=new Intent(this,LocationSessionService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);status.setText("Location sharing started. Android shows an ongoing location notification.");}
 @Override public void onRequestPermissionsResult(int c,String[] p,int[] r){super.onRequestPermissionsResult(c,p,r);boolean ok=r.length>0&&r[0]==android.content.pm.PackageManager.PERMISSION_GRANTED;if(c==103&&ok)enableLocationStart();else if(c==103)status.setText("Location permission denied. Sharing remains off.");else if(c==101||c==102)status.setText(ok?"Permission granted. No capture starts automatically.":"Permission denied. Capture remains off.");}
 @Override protected void onDestroy(){if(listener!=null)listener.remove();super.onDestroy();}
}